Index: api/tests/presenca-fatia1.test.ts
===================================================================
--- api/tests/presenca-fatia1.test.ts	
+++ api/tests/presenca-fatia1.test.ts	
@@ -0,0 +1,60 @@
+import { describe, it, expect, beforeEach, afterEach } from 'vitest';
+import request from 'supertest';
+import path from 'path';
+import os from 'os';
+import fs from 'fs';
+import { createApp } from '../src/app.js';
+
+describe('M3 - Presença - Fatia 1 (R1)', () => {
+  let app: any;
+  let dbPath: string;
+
+  beforeEach(async () => {
+    const tmpDir = os.tmpdir();
+    dbPath = path.join(tmpDir, `test-presenca-${Date.now()}-${Math.random()}.sqlite`);
+    app = createApp({ dbPath, modoTeste: true });
+    await request(app).post('/_teste/reset');
+  });
+
+  afterEach(() => {
+    app?.close?.();
+    if (fs.existsSync(dbPath)) {
+      try {
+        fs.unlinkSync(dbPath);
+      } catch {}
+    }
