import { ActivityRepository } from '../repositories/activity-repository.js';
import { Clock } from '../clock/clock.js';
import { DomainError } from '../domain/activity.js';
import { NotFoundError } from './errors.js';
import { DateTime } from 'luxon';
import crypto from 'crypto';

const ALPHABET = '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';

export interface CodigoDoEncontroResult {
  encontroId: string;
  codigo: string;
  trocaEm: string;
  validoAte: string
}
export class GetCodigoDoEncontroUseCase {
  constructor(
    private readonly activityRepository: ActivityRepository,
    private readonly clock: Clock,
  ) {}

  async execute(encontroId: string): Promise<CodigoDoEncontroResult> {
    const encontroWithActivity = await this.activityRepository.findEncounterWithActivity(encontroId);

    if (!encontroWithActivity) {
      throw new NotFoundError('Encontro não encontrado');
    }

    const now = this.clock.now();
    const minute = now.toFormat('mm');
    const hash = crypto.createHash('sha256')
      .update(encontroId + minute)
      .digest('hex');

    let codigo = '';
    for (let i = 0; i < 6; i++) {
      const index = parseInt(hash.substring(i * 5, i * 5 + 5), 16) % ALPHABET.length;
      codigo += ALPHABET[index];
    }

    const trocaEm = now.plus({ minutes: 1 }).set({ second: 0, millisecond: 0 }).toISO();
    const validoAte = now.plus({minutes: 2}).set({ second: 0, millisecond: 0 }).toISO();

    return {
      encontroId,
      codigo,
      trocaEm,
      validoAte
    };
  }
}
